// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

import {LASShake} from "../src/LASShake.sol";
import {console} from "./TwoLegSwapGas.t.sol";

/// @title LASShakeGrowth — the measured lower bound on how much execution gas on-chain LAS
///        verification gains when the parameter set moves from Dilithium-III to Dilithium-V.
///
/// WHY THIS TEST EXISTS. `LASVerifyOpt` is measured to fit one EIP-7825 transaction at
/// Simplified Dilithium-III. Whether it still fits at Dilithium-V was twice argued from
/// arithmetic alone and twice found unsound:
///
///   1. "Execution can only grow" is not a bound, because calldata byte content is a second
///      free variable. Pushing it the D5-favourable way (every added calldata byte zero) and
///      freezing execution puts D5 *under* the cap with room to spare. A worst case is only a
///      bound when EVERY free variable is pushed the adverse way at once.
///   2. Dividing the measured SHAKE256 stage total by its block count does NOT lower-bound the
///      cost of one added block: the stage total also carries `init()` and the final padding,
///      so the quotient OVERstates per-block cost.
///
/// This test removes both defects by measuring a DIFFERENCE rather than modelling a rate.
/// `absorbPad` is timed over the two preimage lengths the two parameter sets actually hash:
///
///     preimage = pack(t) ‖ pack(w') ‖ M = 2 · n · 1024 + |M|
///     D3 (n=6): 2·6144 + 32 = 12,320 B      D5 (n=8): 2·8192 + 32 = 16,416 B
///
/// The 12,320 figure is the one `LASGasBreakdown` already reports its SHAKE stage against, so
/// the two runs are commensurable. Taking the difference cancels `init()` and the pad-block
/// handling — both lengths leave room for the pad inside their final rate block (12,376−12,320
/// = 56 B and 16,456−16,416 = 40 B), so both take the same code path.
///
/// HOW THE RESULT IS USED. Every stage of `LASVerifyOpt` except one is a deterministic loop
/// over n, ell, n+ell or n·ell, so at D5 each runs strictly more iterations of identical code
/// and cannot cost less than at D3. The single exception is `SampleInBall`, whose rejection
/// loop is data-dependent and could in principle be cheaper at D5 despite kappa growing 49→60.
/// Subtracting its whole measured D3 cost therefore gives a sound lower bound:
///
///     execution_D5  ≥  (execution_D3 − sampleInBall_D3)  +  deltaAbsorb
///
/// `scripts/derive_onchain_d5_bound.py` combines this test's output with the client receipt in
/// `evidence/onchain_onetx/latest/` and the stage attribution in `evidence/onchain/latest/`,
/// and only then decides. This test states no verdict of its own — it emits a measurement.
///
/// ⚠ Run WITHOUT `--gas-report`: the inspector is metered inside the measured frame and
/// inflates `gasleft()` deltas. Same rule as the cap gates in `LASGasBreakdown.t.sol`.
contract LASShakeGrowthTest {
    /// Preimage lengths, derived from `2 · n · POLY_PACKED_BYTES + |M|` with the 32-byte
    /// message that the one-transaction run measured. Kept as literals so the file states
    /// plainly which two points are being compared.
    uint256 constant PREIMAGE_D3 = 12_320; // n = 6
    uint256 constant PREIMAGE_D5 = 16_416; // n = 8
    uint256 constant SHAKE256_RATE = 136;

    /// Deterministic, non-trivial fill. Keccak-f has no data-dependent control flow, so the
    /// cost does not depend on the bytes; filling rather than leaving zeros removes the
    /// question rather than relying on that fact.
    function _buf(uint256 len) internal pure returns (bytes memory b) {
        b = new bytes(len);
        for (uint256 i = 0; i < len; i++) {
            b[i] = bytes1(uint8((i * 31 + 7) & 0xff));
        }
    }

    function _timeAbsorb(bytes memory buf) internal pure returns (uint256 used) {
        uint256 ptr;
        assembly {
            ptr := add(buf, 32)
        }
        uint256 p = LASShake.init();
        uint256 before = gasleft();
        LASShake.absorbPad(p, ptr, buf.length);
        used = before - gasleft();
    }

    /// Emits both absolute costs and their difference. No assertion on the difference itself:
    /// the threshold it must clear is not knowable inside the EVM, because it depends on the
    /// client receipt and on the D5 calldata projection. The Python script owns that decision.
    function test_absorb_growth_D3_to_D5() public pure {
        // Both buffers are allocated before any timing so that memory-expansion gas is paid
        // outside the measured frames, and an untimed warm-up precedes the first measurement
        // (the same discipline the C/Rust benchmark drivers use).
        bytes memory small = _buf(PREIMAGE_D3);
        bytes memory large = _buf(PREIMAGE_D5);
        _timeAbsorb(small); // warm-up, discarded

        uint256 gasD3 = _timeAbsorb(small);
        uint256 gasD5 = _timeAbsorb(large);
        require(gasD5 > gasD3, "absorb did not grow with preimage length");

        // Block counts, for the reader: both include the pad block.
        uint256 blocksD3 = PREIMAGE_D3 / SHAKE256_RATE + 1;
        uint256 blocksD5 = PREIMAGE_D5 / SHAKE256_RATE + 1;

        console.log("SHAKE absorbPad preimage bytes D3 / D5", PREIMAGE_D3, PREIMAGE_D5);
        console.log("SHAKE absorbPad blocks D3 / D5", blocksD3, blocksD5);
        console.log("SHAKE absorbPad gas D3", gasD3);
        console.log("SHAKE absorbPad gas D5", gasD5);
        console.log("SHAKE absorbPad DELTA gas (D5 - D3)", gasD5 - gasD3);
    }

    /// Guards the arithmetic the difference relies on: that the two lengths differ by exactly
    /// the block count the parameter sets imply, and that each leaves room for the pad inside
    /// its final rate block. If either stops holding, the difference stops being 30 blocks of
    /// the same code and the bound above is no longer sound.
    function test_block_arithmetic_holds() public pure {
        uint256 blocksD3 = PREIMAGE_D3 / SHAKE256_RATE + 1;
        uint256 blocksD5 = PREIMAGE_D5 / SHAKE256_RATE + 1;
        require(blocksD5 - blocksD3 == 30, "block delta is not 30");
        require(blocksD3 * SHAKE256_RATE > PREIMAGE_D3, "D3 pad does not fit its final block");
