// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

import {LASShake} from "../src/LASShake.sol";
import {console} from "./TwoLegSwapGas.t.sol";

/// @title LASShakeGrowth — measured inputs for the question "does on-chain LAS verification
///        still fit one EIP-7825 transaction at Dilithium-V?"
///
/// THIS TEST STATES NO VERDICT. It emits measurements. The decision is assembled in
/// `scripts/derive_onchain_d5_bound.py`, where the conservative subtractions are explicit and
/// auditable. That separation is deliberate: the threshold depends on a client receipt and on
/// a calldata projection, neither of which is knowable inside the EVM.
///
/// WHY IT EXISTS. `LASVerifyOpt` is MEASURED to fit at Simplified Dilithium-III. Whether it
/// fits at Dilithium-V was argued from arithmetic three times and found unsound three times:
///
///   1. "Execution can only grow" is not a bound. Calldata byte content is a second free
///      variable, and pushing it the D5-favourable way (every added byte zero) with execution
///      frozen puts D5 *under* the cap. A worst case binds only when EVERY free variable is
///      pushed the adverse way at once.
///   2. Dividing the measured SHAKE stage total by its block count does not lower-bound the
///      cost of one added block: the total also carries `init()` and the pad tail, so the
///      quotient OVERstates per-block cost.
///   3. `SampleInBall` is not the only data-dependent stage. `_decodeZ` branches on coefficient
///      value (`if gt(f, 137935)`), so its cost is signature-dependent too, and neither stage
///      may be assumed to cost at least its D3 value at D5.
///
/// WHAT IS MEASURED, AND WHY THIS FORM. The preimage `pack(t)‖pack(w')‖M = 2·n·1024 + |M|` is
/// 12,320 B at n=6 and 16,416 B at n=8 for the 32-byte message that was measured on chain. The
/// 12,320 figure is what `LASGasBreakdown` already attributes its SHAKE stage against, so the
/// two are commensurable.
///
/// The primary output is the DIFFERENCE of two `absorbPad` measurements. A directly measured
/// difference is the quantity itself, not a model of it — so it does NOT depend on the two
/// lengths sharing a tail path. They do not: D3's final rate block carries 80 data bytes and
/// D5's carries 96, so the difference is 30 permutations *plus* a tail delta, not 30
/// permutations exactly. That is fine here, because the difference is only ever used as a
/// LOWER bound on how much the SHAKE stage grows, and the squeeze that follows it also grows
/// (48 → 64 output bytes, same permutation count), so the stage grows by at least this much.
///
/// `permute` is measured alongside as an independent, data-independent unit cost, so the
/// absorb delta can be sanity-checked against 30 × permute rather than taken on trust.
///
/// ⚠ Run WITHOUT `--gas-report`: the inspector is metered inside the measured frame and
/// inflates `gasleft()` deltas. Same rule as the cap gates in `LASGasBreakdown.t.sol`.
contract LASShakeGrowthTest {
    /// Preimage lengths from `2 · n · POLY_PACKED_BYTES + |M|`, |M| = 32 as measured on chain.
    uint256 constant PREIMAGE_D3 = 12_320; // n = 6
    uint256 constant PREIMAGE_D5 = 16_416; // n = 8
    uint256 constant SHAKE256_RATE = 136;

    ShakeHarness h;

    function setUp() public {
        h = new ShakeHarness();
    }

    /// Each length is timed in its own EXTERNAL call, so every measurement starts from a fresh
    /// memory space. Timing them in one frame would let the first allocation raise the memory
    /// high-water mark that the second is measured against, making the result depend on the
    /// order the two were run in.
    function test_absorb_growth_D3_to_D5() public {
        h.absorbGas(PREIMAGE_D3); // warm-up, discarded

        uint256 gasD3 = h.absorbGas(PREIMAGE_D3);
        uint256 gasD5 = h.absorbGas(PREIMAGE_D5);
        require(gasD5 > gasD3, "absorb did not grow with preimage length");

        uint256 blocksD3 = PREIMAGE_D3 / SHAKE256_RATE + 1;
        uint256 blocksD5 = PREIMAGE_D5 / SHAKE256_RATE + 1;

        console.log("absorbPad preimage bytes D3 / D5", PREIMAGE_D3, PREIMAGE_D5);
        console.log("absorbPad rate blocks D3 / D5", blocksD3, blocksD5);
        console.log("absorbPad gas D3", gasD3);
        console.log("absorbPad gas D5", gasD5);
        console.log("absorbPad DELTA gas D5 minus D3", gasD5 - gasD3);
    }

    /// `permute` is pure Keccak-f: fixed-size state, no memory growth, no data-dependent
    /// control flow. Measuring k and 2k in separate frames and differencing cancels the call
    /// and loop overhead that a single measurement would carry.
    function test_permute_unit_cost() public {
        h.permuteGas(4); // warm-up, discarded

        uint256 g1 = h.permuteGas(8);
        uint256 g2 = h.permuteGas(16);
        require(g2 > g1, "permute loop did not scale");
        uint256 marginal = (g2 - g1) / 8;

        console.log("permute gas for 8 / 16 iterations", g1, g2);
        console.log("permute MARGINAL gas per call", marginal);
    }

    /// Guards the arithmetic the reader will do with these numbers: that the block delta is
    /// what the parameter sets imply, and that each length leaves room for its pad inside the
    /// final rate block (so neither needs an extra all-pad block the other does not).
    function test_block_arithmetic_holds() public pure {
        uint256 blocksD3 = PREIMAGE_D3 / SHAKE256_RATE + 1;
        uint256 blocksD5 = PREIMAGE_D5 / SHAKE256_RATE + 1;
        require(blocksD5 - blocksD3 == 30, "block delta is not 30");
        require(blocksD3 * SHAKE256_RATE > PREIMAGE_D3, "D3 pad does not fit its final block");
        require(blocksD5 * SHAKE256_RATE > PREIMAGE_D5, "D5 pad does not fit its final block");
        console.log("rate-block delta D5 minus D3", blocksD5 - blocksD3);
        console.log("final-block free bytes D3 / D5",
            blocksD3 * SHAKE256_RATE - PREIMAGE_D3, blocksD5 * SHAKE256_RATE - PREIMAGE_D5);
    }
}

/// Separate contract so each measurement is an external call with its own memory space.
contract ShakeHarness {
    /// Keccak-f has no data-dependent control flow, so the fill cannot change the cost;
    /// filling rather than leaving zeros removes the question instead of relying on that.
    function _buf(uint256 len) internal pure returns (bytes memory b) {
        b = new bytes(len);
        for (uint256 i = 0; i < len; i++) {
            b[i] = bytes1(uint8((i * 31 + 7) & 0xff));
        }
    }

    /// Allocation and `init()` are both outside the measured frame, so no memory-expansion
    /// gas lands inside it.
    function absorbGas(uint256 len) external pure returns (uint256 used) {
        bytes memory buf = _buf(len);
        uint256 ptr;
        assembly {
            ptr := add(buf, 32)
        }
        uint256 p = LASShake.init();
        uint256 before = gasleft();
        LASShake.absorbPad(p, ptr, len);
        used = before - gasleft();
    }

    function permuteGas(uint256 iterations) external pure returns (uint256 used) {
        uint256 p = LASShake.init();
        uint256 before = gasleft();
        for (uint256 i = 0; i < iterations; i++) {
            LASShake.permute(p);
        }
        used = before - gasleft();
    }
}

