        uint256 p = LASShake.init();
        uint256 before = gasleft();
        LASShake.absorbPad(p, ptr, len);
        used = before - gasleft();
    }

    function permute8() external pure returns (uint256 used) {
        uint256 p = LASShake.init();
        uint256 before = gasleft();
        LASShake.permute(p);
        LASShake.permute(p);
        LASShake.permute(p);
