        LASShake.permute(p);
        LASShake.permute(p);
        LASShake.permute(p);
        LASShake.permute(p);
        used = before - gasleft();
    }

    function permute16() external pure returns (uint256 used) {
        uint256 p = LASShake.init();
        uint256 before = gasleft();
        LASShake.permute(p);
        LASShake.permute(p);
        LASShake.permute(p);
        LASShake.permute(p);
