        bytes memory sig = vm.readFileBinary("test/vectors/d2/sig.bin");
        bytes memory aHatP = _packBE(_toNtt(_readPolys("pp_normal.bin", A_POLYS)));
        bytes memory tHatP = _packBE(_toNtt(_readPolys("t.bin", T_POLYS)));
