        bytes calldata aHatPacked,
        bytes calldata tHatPacked,
        bytes calldata tPacked,
        bytes calldata message,
        bytes calldata sig
    ) external pure returns (bool) {
        return LASVerifyOptD2.verify(aHatPacked, tHatPacked, tPacked, message, sig);
    }
}

