\section{Application demonstration}
\label{sec:res-app}

% A deliberately non-technical picture of the application, placed before the protocol
% diagram so a reader meets the goal before the mechanism (supervisor request,
% Meeting 10). Parties keep the paper's u_1/u_2 labels.
\begin{figure}[htbp]
  \centering
  \begin{tikzpicture}[
      font=\small,
      party/.style={draw, rounded corners=3pt, align=center, minimum width=34mm,
                    minimum height=15mm, line width=0.5pt},
      coin/.style={draw, circle, minimum size=8mm, inner sep=0pt, font=\footnotesize\bfseries},
      lbl/.style={font=\footnotesize\itshape, align=center},
      >={Stealth[]}]

    \node[party, fill=orange!12, draw=orange!60!black] (a) at (0,0)
      {$u_1$ \\[1pt] \footnotesize on chain~A};
    \node[party, fill=blue!10, draw=blue!60!black] (b) at (72mm,0)
      {$u_2$ \\[1pt] \footnotesize on chain~B};

    \node[coin, fill=orange!30, draw=orange!60!black] (ca) at ($(a)+(0,13mm)$) {\ding{'102}};
    \node[coin, fill=blue!25, draw=blue!60!black]     (cb) at ($(b)+(0,13mm)$) {\ding{'103}};
    \node[lbl, above=1mm of ca] {coin on chain~A};
    \node[lbl, above=1mm of cb] {coin on chain~B};

    % the two transfers, drawn crossing to show the exchange
    \draw[->, line width=1pt, orange!70!black]
      (a.north east) to[out=35, in=145] node[lbl, above, pos=0.5] {A's coin $\to u_2$} (b.north west);
    \draw[->, line width=1pt, blue!70!black]
      (b.south west) to[out=-145, in=-35] node[lbl, below, pos=0.5] {B's coin $\to u_1$} (a.south east);

    \node[draw, rounded corners=2pt, fill=green!8, draw=green!45!black,
          align=center, font=\footnotesize, minimum width=58mm] (g) at (36mm,-24mm)
      {\textbf{Either both transfers happen, or neither does.}\\
       No exchange, no escrow agent, nobody to trust.};
  \end{tikzpicture}
  \caption[An atomic swap, in outline]{What the application is for, before any
  cryptography. Two parties on two different chains want to trade coins directly. The
  danger is that one side takes payment and walks away; an atomic swap removes it, so
  either both transfers settle or neither does, with no exchange and no trusted third
  party. \Cref{fig:swapflow} shows how the adaptor signature actually achieves this.}
  \label{fig:swapidea}
\end{figure}

\section{Application demonstration}
\label{sec:res-app}

% A deliberately non-technical picture of the application, placed before the protocol
% diagram so a reader meets the goal before the mechanism (supervisor request, Meeting 10).
% The chains are attached to the COINS, not to the parties: each party acts on both chains.
% Absolute coordinates only -- no calc library, no pifont.
\begin{figure}[htbp]
  \centering
  \begin{tikzpicture}[
      font=\small,
      party/.style={draw, rounded corners=3pt, align=center, minimum width=26mm,
                    minimum height=12mm, line width=0.6pt},
      coin/.style={draw, rounded corners=2pt, align=center, font=\footnotesize,
                   minimum width=26mm, minimum height=9mm},
      lbl/.style={font=\footnotesize\itshape, align=center},
      >={Stealth[]}]

    \node[party, fill=orange!12, draw=orange!60!black] (a) at (0mm,0mm)   {Alice};
    \node[party, fill=blue!10,  draw=blue!60!black]    (b) at (76mm,0mm)  {Bob};

    \node[coin, fill=orange!25, draw=orange!60!black] (ca) at (0mm,16mm)  {a coin on chain~A};
    \node[coin, fill=blue!20,  draw=blue!60!black]    (cb) at (76mm,16mm) {a coin on chain~B};

    % the two transfers, crossing, to show it is an exchange
    \draw[->, line width=1pt, orange!70!black]
      (ca.east) to[out=20, in=160]
      node[lbl, above, pos=0.5] {chain-A coin $\to$ Bob} (cb.west);
    \draw[->, line width=1pt, blue!70!black]
      (b.west) to[out=200, in=-20]
      node[lbl, below, pos=0.5] {chain-B coin $\to$ Alice} (a.east);

    \node[draw, rounded corners=2pt, fill=green!8, draw=green!45!black,
          align=center, font=\footnotesize, minimum width=64mm] at (38mm,-20mm)
      {\textbf{Either both transfers happen, or neither does.}\\
       No exchange, no escrow, no trusted intermediary.};
  \end{tikzpicture}
  \caption[An atomic swap, in outline]{What the application is for, before any
  cryptography. Two parties want to trade coins that live on two different chains. The
  danger is that one side takes payment and walks away; an atomic swap removes it, so
  either both transfers settle or neither does, without a trusted intermediary. Each
  party acts on \emph{both} chains --- the chains belong to the coins, not to the people.
  \Cref{fig:swapflow} shows how the adaptor signature achieves this.}
  \label{fig:swapidea}
\end{figure}

